local function desenhar()
  return {
    { item = "minecraft:book", label = "Meu primeiro menu" },
    { item = "minecraft:barrier", label = "Fechar" }
  }
end

mod.menu("balcao", function(ctx)
  if ctx.player == nil then return end
  if ctx.menu.slot == 1 then
    ctx.player.close_menu()
  end
end)

mod.command("loja", function(ctx)
  if ctx.player == nil then return end
  ctx.player.open_menu("balcao", "Meu menu", 1, desenhar())
end)
